  <footer>Made with a wee bit o' love from Scotland</footer>
<script>
(() => {
  // Parts of the joke
  const intros = [
    "Why did the Scot bring a",
    "How come the bairn's",
    "What's a Scotsman's favourite",
    "Did ye hear about the lassie with a",
    "Why does every Glasgow dog have a",
    "What do ye call a Highland cow that can",
    "Why did the kilt refuse to",
