    "What’s the secret to a Scotsman's luck with a",
    "Why do Scots never forget their",
    "What did the Scotsman say when given a",
    "How come every Scotsman’s grandad had a"
  ];

  const middles = [
    "bagpipe at the supper table?",
    "haggis always come out perfect?",
    "whisky bottle come with a map?",
