    "ceilidh dancer cannae sit still?",
    "bannock make the best football?",
    "Aberdeen cattle know a secret joke?",
    "glen kept a fire burning all winter?"
  ];

  const punchlines = [
    "Because even supper needs a sound track!",
    "She followed the recipe in the clan cookbook, of course!",
    "To find your way safely home after a dram or two!",
    "Cause tartan’s style is older than the hills!",
    "Because shortbread’s the best game in town!",
    "Because every loch loves a good splash!",
    "It’s got more savings than the Royal Bank of Scotland!",
    "Cause you never know when you’ll be tossing one next!",
    "They've got a spring in their step that’s all Highland magic!",
    "Because nothing beats a well-kicked bannock!",
    "They’re always laughing at themselves – it’s part of the charm!",
    "Because a warm glen keeps the bairns happy!"
  ];

  const jokeEl = document.getElementById('joke');
  const btn = document.getElementById('newJoke');

  function randIndex(arr) {
    return Math.floor(Math.random() * arr.length);
  }

  function generateJoke() {
    // Pick parts ensuring no repetition in one joke
    // Shuffle indices to avoid accidental repeats of same index in 3 parts

    const i = randIndex(intros);
    let m = randIndex(middles);
    while(m === i) m = randIndex(middles);
    let p = randIndex(punchlines);
    while(p === i || p === m) p = randIndex(punchlines);

    // Build the joke
    const joke = `${intros[i]} ${middles[m]}<br><br><strong>${punchlines[p]}</strong>`;

    return joke;
  }

  function showJoke() {
    jokeEl.innerHTML = generateJoke();
  }

  btn.addEventListener('click', showJoke);

  // Show the first joke on load
  showJoke();
})();
