<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Scottish Joke Generator</title>
  <style>
    body {
      background: #224c31;
      color: #fff;
      font-family: sans-serif;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-direction: column;
      padding: 0 1em;
    }
    .container {
      background: rgba(255,255,255,0.07);
      padding: 2em 2em 1.5em 2em;
      border-radius: 18px;
      box-shadow: 0 5px 26px -4px #0006;
      max-width: 430px;
      text-align: center;
    }
    .joke {
      font-size: 1.3em;
      margin-bottom: 2em;
      min-height: 2.7em;
      line-height: 1.5;
      letter-spacing: 0.01em;
      transition: opacity 0.2s;
    }
    button {
      background: #2e814e;
      color: #fff;
      border: none;
      border-radius: 13px;
      padding: 0.8em 2em;
      font-size: 1.1em;
      font-weight: bold;
      cursor: pointer;
      box-shadow: 0 4px 16px -10px #0006;
      transition: background 0.15s;
    }
    button:hover {
      background: #3dc06d;
    }
    .title {
      font-family: inherit;
      font-size: 2em;
      margin-bottom: 0.3em;
      letter-spacing: 0.04em;
      color: #c7ffce;
      text-shadow: 1px 3px 8px #1432187a;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="title">Scottish Joke Generator</div>
    <div class="joke" id="joke"></div>
    <button onclick="newJoke()">Tell me another</button>
  </div>
<script>
const setups = [
  "Why did the {{noun}} {{verb}} {{preposition}} the {{adjective}} {{object}}?",
  "What do you call a {{adjective}} {{noun}} in {{place}}?",
  "How does a {{noun}} {{verb2}} their {{object}}?",
  "Why do {{pluralNoun}} never {{verb3}} on a {{weather}} day?",
  "Did you hear about the {{adjective}} {{noun}} who {{verb4}} a {{object}}?",
];

const nouns = ["Scotsman", "bagpiper", "Loch Ness Monster", "haggis", "Highlander", "ceilidh dancer", "sheep", "kilt-maker"];
const verbs = ["march", "leap", "tango", "wade", "amble", "sprint", "sneak", "stomp"];
const prepositions = ["through", "past", "around", "over", "under"];
const adjectives = ["wee", "cheery", "brave", "braw", "mighty", "bonnie", "sleepy", "mischievous"];
const objects = ["thistle", "castle", "loch", "deep-fried Mars bar", "kilts", "sporran", "pub", "tartan scarf"];
const places = ["Edinburgh", "Glasgow", "the Highlands", "a ceilidh", "the pub", "Ben Nevis", "Inverness", "the glen"];
const verbs2 = ["tune", "prepare", "find", "wash", "hide", "decorate", "fold", "prepare"];
const verb3 = ["complain", "dance", "sing", "argue", "wear kilts", "have porridge", "drink tea", "skip work"];
const weather = ["rainy", "windy", "misty", "dreich", "sunny", "snowy"];
const pluralNouns = ["Scots", "bagpipers", "sheep", "Highlanders", "ceilidh dancers", "haggises"];
const verb4 = ["finds", "bakes", "loses", "borrows", "builds", "shares", "paints", "invents"];

const punchlineStarts = [
  "Because",
  "Only in Scotland would",
  "It’s because",
  "Legend says",
  "Apparently",
  "The secret is",
  "That's why",
  "Turns out",
  "Little did they know,",
];

const punchlineEndings = [
  "they dinnae have enough shortbread for the journey.",
  "the bagpipes were already playing themselves.",
  "it was afraid Nessie would photobomb their selfie.",
  "their kilts were stuck in the laundry.",
  "they wanted to keep their tartan dry.",
  "the ceilidh had run out of Irn-Bru.",
  "the castle ghost needed a dance partner.",
  "their sporran was too full of biscuits.",
  "the wind wouldnae stop, so neither did they.",
  "they were following a trail of oatcakes.",
  "someone shouted 'last orders' at the pub.",
  "even the rain had a Scottish accent that day.",
];

function template(str, map) {
  return str
    .replace(/\{\{noun\}\}/g, map.noun)
    .replace(/\{\{verb\}\}/g, map.verb)
    .replace(/\{\{preposition\}\}/g, map.preposition)
    .replace(/\{\{adjective\}\}/g, map.adjective)
    .replace(/\{\{object\}\}/g, map.object)
    .replace(/\{\{place\}\}/g, map.place)
    .replace(/\{\{verb2\}\}/g, map.verb2)
    .replace(/\{\{verb3\}\}/g, map.verb3)
    .replace(/\{\{weather\}\}/g, map.weather)
    .replace(/\{\{pluralNoun\}\}/g, map.pluralNoun)
    .replace(/\{\{verb4\}\}/g, map.verb4);
}

function rand(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

function newJoke() {
  const setupTemplate = rand(setups);
  const map = {
    noun: rand(nouns),
    verb: rand(verbs),
    preposition: rand(prepositions),
    adjective: rand(adjectives),
    object: rand(objects),
    place: rand(places),
    verb2: rand(verbs2),
    verb3: rand(verb3),
    weather: rand(weather),
    pluralNoun: rand(pluralNouns),
    verb4: rand(verb4)
  };

  const setup = template(setupTemplate, map);
  const punchline = rand(punchlineStarts) + " " + rand(punchlineEndings);

  document.getElementById("joke").style.opacity = 0;
  setTimeout(() => {
    document.getElementById("joke").innerHTML = setup + "<br><br><em>" + punchline + "</em>";
    document.getElementById("joke").style.opacity = 1;
  }, 200);
}

window.onload = newJoke;
</script>
</body>
</html>
